/* 识字 Zeichentrainer — the app's own texts in other languages (v253, H: "Multi language UI and translations").
   English is the key: t("Save card") looks the sentence up in the current language and falls back to the English text
   itself, so a missing translation shows English, never a key. {0}, {1} … are filled in by t(); a count word ("card",
   "cards") may carry the number as {0} where the language puts it elsewhere ("カード{0}枚"). The learning content stays
   Chinese, pinyin and the meaning; the owner's tools (Diagnostics, All users, Feedback, the usage report) stay English.
   To add a language: one more entry in LANGS and one more column below. */
const LANGS=[["en","English"],["de","Deutsch"],["fr","Français"],["es","Español"],["ja","日本語"],["ko","한국어"]];
const LANG_LOCALE={en:"en-GB",de:"de-DE",fr:"fr-FR",es:"es-ES",ja:"ja-JP",ko:"ko-KR"};
const LANG_NAME={en:"English",de:"German",fr:"French",es:"Spanish",ja:"Japanese",ko:"Korean"}; /* the languages' English names, for the AI's prompt (v256) */
let LANG="en";
function langDefault(){ const l=String(navigator.language||"").toLowerCase().slice(0,2); return LANGS.some(([c])=>c===l)?l:"en"; }
function t(key,...args){ const d=L10N[LANG]; let s=d&&d[key]!=null?d[key]:null; if(s==null) s=L10N.en&&L10N.en[key]!=null?L10N.en[key]:key; /* a key with a prefix ("capsule:Done") has its English in the en column */ return args.length?s.replace(/\{(\d)\}/g,(m,i)=>args[+i]!=null?args[+i]:m):s; }
/* a count with its word: nOf(3,"card") → "3 cards" / "3 Karten" / "カード3枚"; pl = an irregular plural key */
function nOf(n,w,pl){ n=n||0; const key=n===1?w:(pl||w+"s"), d=L10N[LANG], tr=d&&d[key]!=null?d[key]:key; return tr.includes("{0}")?tr.replace("{0}",n):`${n} ${tr}`; }
